  v_texcoord = texcoord;
  v_tangent = vec4(mat3(frame_info.model) * (rotation * tangent.xyz), tangent.w);
  v_color = color * i_color;
  v_lightmap_uv = vec2(0.0);
  gl_Position = frame_info.mvp * local;
}

