  v_color = i_color;
  v_world_position = world;
  // Uniform scale leaves a normal a normal, which is the second reason the
  // scale is one number.
  v_normal = normal;

  gl_Position = particle_mesh_info.view_projection * vec4(world, 1.0);
}

